const data = $input.first().json;
const recent = data.filings.recent;

const filings = [];

for (let i = 0; i < recent.form.length; i++) {
  const form = recent.form[i];

  // Only 10-K and 10-Q
  if (form !== '10-K' && form !== '10-Q') {
    continue;
  }

  filings.push({
    company: data.name,
    ticker: data.tickers?.[0] || '',
    cik: data.cik,
    form: form,
    filingDate: recent.filingDate[i],
    accessionNumber: recent.accessionNumber[i],
    primaryDocument: recent.primaryDocument[i],

    filingUrl: `https://www.sec.gov/Archives/edgar/data/${data.cik.replace(/^0+/, '')}/${recent.accessionNumber[i].replace(/-/g, '')}/${recent.primaryDocument[i]}`
  });
}

// Sort newest first
filings.sort(
  (a, b) => new Date(b.filingDate) - new Date(a.filingDate)
);

// Return ONLY the latest filing
return [
  {
    json: filings[0]
  }
];

const html = $json.data || '';

if (!html) {
  throw new Error('SEC filing data is empty');
}

// ---------------------------------------------
// Convert HTML to readable text
// ---------------------------------------------

let text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&#160;/gi, ' ')
  .replace(/&#8212;/gi, '—')
  .replace(/&#8217;/gi, "'")
  .replace(/&#8220;/gi, '"')
  .replace(/&#8221;/gi, '"')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&#39;/gi, "'")
  .replace(/&quot;/gi, '"')
  .replace(/\s+/g, ' ')
  .trim();

const normalized = text.toLowerCase();

// ---------------------------------------------
// RISK FACTORS
// ---------------------------------------------

const riskMatches = [
  ...text.matchAll(/item\s+1a\.?\s+risk\s+factors/gi)
];

let riskStart = -1;

if (riskMatches.length > 0) {
  // Last occurrence avoids Table of Contents
  riskStart = riskMatches[riskMatches.length - 1].index;
}

// ---------------------------------------------
// MD&A
// ---------------------------------------------

const mdaPatterns = [
  /item\s+2\.?\s+management['’]s?\s+discussion\s+and\s+analysis/gi,
  /item\s+2\.?\s+management\s+discussion\s+and\s+analysis/gi,
  /management['’]s?\s+discussion\s+and\s+analysis/gi,
  /management\s+discussion\s+and\s+analysis/gi
];

let mdaStart = -1;

for (const pattern of mdaPatterns) {

  const matches = [
    ...text.matchAll(pattern)
  ];

  if (matches.length > 0) {

    // Use the LAST occurrence
    mdaStart = matches[matches.length - 1].index;

    break;
  }
}

// ---------------------------------------------
// RISK FACTORS EXTRACTION
// ---------------------------------------------

let riskFactors = '';

if (riskStart !== -1) {

  let riskEnd = text.length;

  // Risk Factors normally ends before Item 2
  const afterRisk = text.substring(riskStart + 20);

  const endMatches = [
    ...afterRisk.matchAll(
      /item\s+2\.?\s+(?:unregistered\s+sales|management|management['’]s)/gi
    )
  ];

  if (endMatches.length > 0) {

    const candidate =
      riskStart +
      20 +
      endMatches[0].index;

    if (candidate > riskStart) {
      riskEnd = candidate;
    }
  }

  riskFactors = text
    .substring(riskStart, riskEnd)
    .trim();
}

// ---------------------------------------------
// MD&A EXTRACTION
// ---------------------------------------------

let mda = '';

if (mdaStart !== -1) {

  let mdaEnd = Math.min(
    mdaStart + 150000,
    text.length
  );

  const afterMda = text.substring(mdaStart + 20);

  const endMatches = [
    ...afterMda.matchAll(
      /item\s+3\.?\s+(?:quantitative|controls|controls\s+and\s+procedures)/gi
    )
  ];

  if (endMatches.length > 0) {

    const candidate =
      mdaStart +
      20 +
      endMatches[0].index;

    if (candidate > mdaStart) {
      mdaEnd = Math.min(candidate, mdaEnd);
    }
  }

  mda = text
    .substring(mdaStart, mdaEnd)
    .trim();
}

// ---------------------------------------------
// RETURN
// ---------------------------------------------

return [
  {
    json: {
      riskFactors,
      mda,

      riskFactorsFound: riskStart !== -1,
      mdaFound: mdaStart !== -1,

      extractedTextLength: text.length
    }
  }
];

const items = $input.all();

const extracted = items.find(item => item.json.riskFactors || item.json.mda)?.json || {};
const metadata = items.find(item => item.json.company || item.json.ticker)?.json || {};

return [
  {
    json: {
      company: metadata.company || "",
      ticker: metadata.ticker || "",
      cik: metadata.cik || "",
      form: metadata.form || "",
      filingDate: metadata.filingDate || "",
      accessionNumber: metadata.accessionNumber || "",
      primaryDocument: metadata.primaryDocument || "",
      filingUrl: metadata.filingUrl || "",

      riskFactors: extracted.riskFactors || "",
      mda: extracted.mda || "",

      riskFactorsFound: extracted.riskFactorsFound || false,
      mdaFound: extracted.mdaFound || false,
      extractedTextLength: extracted.extractedTextLength || 0
    }
  }
];

const data = $input.first().json;

const sourceText = `${data.riskFactors || ""}\n${data.mda || ""}`;

// Keywords that are useful for financial/risk analysis
const keywords = [
  "risk",
  "materially adversely",
  "revenue",
  "net sales",
  "gross margin",
  "operating income",
  "operating expenses",
  "net income",
  "cash flow",
  "liquidity",
  "debt",
  "tariff",
  "tariffs",
  "supply",
  "demand",
  "competition",
  "regulatory",
  "litigation",
  "legal",
  "macroeconomic",
  "inflation",
  "interest rate",
  "foreign currency",
  "outlook",
  "expects",
  "expect",
  "uncertainty",
  "uncertain",
  "cost",
  "margin"
];

// Split into sentences
const sentences = sourceText
  .replace(/\s+/g, " ")
  .split(/(?<=[.!?])\s+/);

// Keep sentences containing important keywords
const relevantSentences = sentences.filter(sentence => {
  const lower = sentence.toLowerCase();

  return keywords.some(keyword => lower.includes(keyword));
});

// Remove duplicates
const uniqueSentences = [...new Set(relevantSentences)];

// Limit total text sent to Groq
const MAX_CHARS = 18000;

let selectedText = "";

for (const sentence of uniqueSentences) {
  if ((selectedText.length + sentence.length + 1) > MAX_CHARS) {
    break;
  }

  selectedText += sentence + " ";
}

return [
  {
    json: {
      company: data.company,
      ticker: data.ticker,
      form: data.form,
      filingDate: data.filingDate,
      accessionNumber: data.accessionNumber,
      filingUrl: data.filingUrl,

      relevantText: selectedText.trim(),

      originalTextLength: sourceText.length,
      relevantTextLength: selectedText.length,
      sentencesFound: uniqueSentences.length
    }
  }
];

