const response = $input.first().json;

// ===============================
// 1. Get AI output
// ===============================
const output = response.output?.[0]?.content?.[0]?.text || "";

if (!output) {
  throw new Error("AI response text not found");
}

// Remove markdown code fences
const cleaned = output
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

let analysis;

try {
  analysis = JSON.parse(cleaned);
} catch (error) {
  throw new Error("AI response is not valid JSON: " + error.message);
}


// ===============================
// 2. Get original SEC filing data
// ===============================
const filing = $('Code - Get Latest Filing').first().json;


// ===============================
// 3. Combine SEC data + AI analysis
// ===============================
return [
  {
    json: {

      // SEC / Company information
      company: filing.company || "",
      ticker: filing.ticker || "",
      cik: filing.cik || "",
      form: filing.form || "",
      filingDate: filing.filingDate || "",
      accessionNumber: filing.accessionNumber || "",
      primaryDocument: filing.primaryDocument || "",
      filingUrl: filing.filingUrl || "",

      // AI Analysis
      overallSentiment: analysis.overallSentiment || "",
      riskLevel: analysis.riskLevel || "",
      riskSummary: analysis.riskSummary || "",
      keyRisks: analysis.keyRisks || [],
      businessOutlook: analysis.businessOutlook || "",
      financialHighlights: analysis.financialHighlights || [],
      investorTakeaway: analysis.investorTakeaway || ""
    }
  }
];
